public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (!visited[i][j] && isOil(grid[i][j])) {
                deposits++;
                exploreDeposit(grid, visited, i, j);
            }
        }
    }

    return deposits;
}

private static boolean isOil(char c) {
    return c != null && c != '*' && c != ' ';
}

private static void exploreDeposit(char[][] grid, boolean[][] visited, int row, int col) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[row].length) {
        return;
    }
    if (visited[row][col] || !isOil(grid[row][col])) {
        return;
    }
    visited[row][col] = true;
    exploreDeposit(grid, visited, row - 1, col);
    exploreDeposit(grid, visited, row + 1, col);
    exploreDeposit(grid, visited, row, col - 1);
    exploreDeposit(grid, visited, row, col + 1);
}
