public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null) {
        throw new IllegalArgumentException("Start and end coordinates cannot be null");
    }
    if (start.length != end.length) {
        throw new IllegalArgumentException("Start and end coordinates must have the same length");
    }

    // Build adjacency list
    List<List<Integer>>[] graph = new List[n * n];
    for (int i = 0; i < graph.length; i++) {
        graph[i] = new ArrayList<>();
    }

    // Add paths to the graph
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 2) {
                continue;
            }
            int from = path[0];
            int to = path[1];
            if (from >= 0 && from < n * n && to >= 0 && to < n * n) {
                graph[from].add(to);
                graph[to].add(from); // Assuming undirected paths
            }
        }
    }

    // Helper method to convert 1D index to 2D coordinates
    int[] startCoord = new int[2];
    int[] endCoord = new int[2];

    if (start.length == 2) {
        startCoord[0] = start[0];
        startCoord[1] = start[1];
    } else if (start.length == 1) {
        startCoord[0] = start[0] / n;
        startCoord[1] = start[0] % n;
    } else if (start.length == 0) {
        startCoord[0] = 0;
        startCoord[1] = 0;
    } else {
        throw new IllegalArgumentException("Invalid start coordinate length");
    }

    if (end.length == 2) {
        endCoord[0] = end[0];
        endCoord[1] = end[1];
    } else if (end.length == 1) {
        endCoord[0] = end[0] / n;
        endCoord[1] = end[0] % n;
    } else if (end.length == 0) {
        endCoord[0] = 0;
        endCoord[1] = 0;
    } else {
        throw new IllegalArgumentException("Invalid end coordinate length");
    }

    // Convert 2D coordinates to 1D index
    int startIndex = startCoord[0] * n + startCoord[1];
    int endIndex = endCoord[0] * n + endCoord[1];

    // Validate indices
    if (startIndex < 0 || startIndex >= n * n || endIndex < 0 || endIndex >= n * n) {
        throw new IllegalArgumentException("Start or end index out of bounds");
    }

    // BFS to find if path exists
    Set<Integer> visited = new HashSet<>();
    Queue<Integer> queue = new LinkedList<>();

    queue.offer(startIndex);
    visited.add(startIndex);

    while (!queue.isEmpty()) {
        int currentNode = queue.poll();
        if (currentNode == endIndex) {
            return "can be travelled";
        }

        for (int neighbor : graph[currentNode]) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}
