public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "Error: Input words cannot be null.";
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int commonCount = 0;
    for (int i = 0; i < word1.length(); i++) {
        char c = word1.charAt(i);
        if (word2.indexOf(c) >= 0) {
            commonCount++;
        }
    }

    int totalLength = word1.length() + word2.length();

    if (commonCount == 0) {
        return "appx(" + word1.toLowerCase() + ", " + word2.toLowerCase() + ") = 0";
    }

    int gcd = getGcd(commonCount, totalLength);
    int numerator = commonCount / gcd;
    int denominator = totalLength / gcd;

    if (denominator == 1) {
        return "appx(" + word1.toLowerCase() + ", " + word2.toLowerCase() + ") = " + numerator;
    } else {
        return "appx(" + word1.toLowerCase() + ", " + word2.toLowerCase() + ") = " + numerator + "/" + denominator;
    }
}

private static int getGcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
