    // Precompute which pairs sum to a perfect square
    boolean[][] isSquarePair = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int root = (int) Math.sqrt(sum);
            if (root * root == sum || (root + 1) * (root + 1) == sum) {
                isSquarePair[i][j] = true;
            }
        }
    }

    boolean[] visited = new boolean[n];
    int[] count = {0};

    backtrackSquarePerm(A, isSquarePair, visited, 0, -1, count, n);

    return count[0];
}

private static void backtrackSquarePerm(int[] A, boolean[][] isSquarePair, boolean[] visited, int depth, int lastIdx, int[] count, int n) {
    if (depth == n) {
        count[0]++;
        return;
    }

    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;

        // Skip duplicates: if same value as a previous unvisited index, skip
        boolean skip = false;
        for (int j = 0; j < i; j++) {
            if (A[i] == A[j] && !visited[j]) {
                skip = true;
                break;
            }
        }
        if (skip) continue;

        // Check adjacency constraint
        if (lastIdx != -1 && !isSquarePair[lastIdx][i]) {
            continue;
        }

        visited[i] = true;
        backtrackSquarePerm(A, isSquarePair, visited, depth + 1, i, count, n);
        visited[i] = false;
    }
}
