public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];

    int idx = 0;

    // There are m + n - 1 diagonals
    for (int d = 0; d < m + n - 1; d++) {
        // For diagonal d, the elements start at row = max(0, d - n + 1) and go down
        // while column = d - row
        int startRow = Math.max(0, d - n + 1);
        int endRow = Math.min(m - 1, d);

        if (d % 2 == 0) {
            // Go from bottom to top (reverse direction)
            for (int r = endRow; r >= startRow; r--) {
                int c = d - r;
                result[idx++] = mat[r][c];
            }
        } else {
            // Go from top to bottom (normal direction)
            for (int r = startRow; r <= endRow; r++) {
                int c = d - r;
                result[idx++] = mat[r][c];
            }
        }
    }

    return result;
}
