public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the rightmost digit that is smaller than a digit to its right
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit exists, the number is non-increasing and no permutation greater than n exists
    if (i < 0) {
        return -1;
    }

    // Step 2: Find the smallest digit to the right of i that is greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Sort the digits after position i in ascending order to get the smallest number
    // We need to reverse the portion after i since it was in non-increasing order
    for (int left = i + 1, right = len - 1; left < right; left++, right--) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
    }

    int result;
    try {
        result = Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }

    // Check if result is actually greater than n (should be by construction, but just to be safe)
    if (result <= n) {
        return -1;
    }

    return result;
}
