public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) {
        return result;
    }

    // The pairs of center symmetric digits
    int[][] pairs = {{0, 0}, {1, 1}, {6, 9}, {8, 8}, {9, 6}};

    if (n % 2 == 0) {
        int half = n / 2;
        generateSymmetric(result, pairs, n, 0, new char[n]);
    } else {
        int half = (n - 1) / 2;
        // For odd length, the middle character must be 0, 1, or 8
        char[] centerDigits = {'0', '1', '8'};
        for (char center : centerDigits) {
            generateSymmetricWithCenter(result, pairs, n, 0, new char[n], center);
        }
    }

    return result;
}

private static void generateSymmetric(List<String> result, int[][] pairs, int n, int pos, char[] arr) {
    int half = n / 2;
    if (pos == half) {
        result.add(new String(arr));
        return;
    }

    for (int[] pair : pairs) {
        arr[pos] = (char) ('0' + pair[0]);
        arr[n - 1 - pos] = (char) ('0' + pair[1]);
        generateSymmetric(result, pairs, n, pos + 1, arr);
    }
}

private static void generateSymmetricWithCenter(List<String> result, int[][] pairs, int n, int pos, char[] arr, char center) {
    int half = (n - 1) / 2;
    if (pos == half) {
        arr[pos] = center;
        result.add(new String(arr));
        return;
    }

    for (int[] pair : pairs) {
        arr[pos] = (char) ('0' + pair[0]);
        arr[n - 1 - pos] = (char) ('0' + pair[1]);
        generateSymmetricWithCenter(result, pairs, n, pos + 1, arr, center);
    }
}
