    public static boolean isBoomerang(int[][] points) {
        if (points == null || points.length != 3) {
            return false;
        }
        for (int i = 0; i < points.length; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }

        // Calculate the cross product to determine if the three points are colinear
        // Cross product of v1 = points[1] - points[0] and v2 = points[2] - points[0]
        long v1x = (long) points[1][0] - points[0][0];
        long v1y = (long) points[1][1] - points[0][1];
        long v2x = (long) points[2][0] - points[0][0];
        long v2y = (long) points[2][1] - points[0][1];

        // If the cross product is zero, the points are colinear (not a valid boomerang)
        long crossProduct = v1x * v2y - v1y * v2x;

        return crossProduct != 0;
    }
