public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    Set<Integer> seen = new HashSet<>();
    Set<Integer> repeated = new HashSet<>();
    int sum = 0;

    for (int num : nums) {
        if (repeated.contains(num)) {
            continue;
        } else if (seen.contains(num)) {
            repeated.add(num);
            sum -= num;
        } else {
            seen.add(num);
            sum += num;
        }
    }

    return sum;
}
