public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }

    // Check if n is a perfect square
    int sqrt = (int) Math.sqrt(n);
    if (sqrt * sqrt == n) {
        return 1;
    }

    // Check if n can be expressed as sum of two perfect squares
    for (int i = sqrt; i >= 1; i--) {
        int remaining = n - i * i;
        int sqrtRem = (int) Math.sqrt(remaining);
        if (sqrtRem * sqrtRem == remaining) {
            return 2;
        }
    }

    // Check if n can be expressed as sum of three perfect squares
    // According to Legendre's three-square theorem, a number n can be represented as sum of three squares
    // if and only if n is not of the form 4^a * (8b + 7)
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 != 7) {
        return 3;
    }

    // By Lagrange's four-square theorem, every natural number is the sum of four integer squares.
    return 4;
}
